import fs from 'node:fs';
import assert from 'node:assert/strict';
const dir='docs/research/photo-fill-20261107',read=f=>JSON.parse(fs.readFileSync(f,'utf8')),save=(f,v)=>fs.writeFileSync(f,JSON.stringify(v,null,2)+'\n');
const files=fs.readdirSync('backend/src/main/resources/catalog').filter(f=>f.endsWith('.json'));
const catalogs=files.map(file=>({file,data:read('backend/src/main/resources/catalog/'+file)}));
const approved=read(dir+'/approved.json'),contexts=read(dir+'/property-context-photos.json'),proof=read(dir+'/primary-license-proof.json');
const reviewFiles=['review-snapshot-239.json','review-wave-new-43.json','review-priority-9.json','review-priority-12.json','review-priority-final.json',...['1','2','3'].map(n=>'../photo-multisource-20261107/review-wave-'+n+'.json')];
reviewFiles.push('../photo-multisource-20261107/review-core-free.json');
const reviewed=[...new Map(reviewFiles.filter(f=>fs.existsSync(dir+'/'+f)).flatMap(f=>read(dir+'/'+f)).map(p=>[p.id+'|'+p.placeId,p])).values()];
const selection=new Set(approved.map(p=>p.id+'|'+p.placeId));
save(dir+'/review-log.json',reviewed.map(p=>({id:p.id,placeId:p.placeId,sourceUrl:p.sourceUrl,status:selection.has(p.id+'|'+p.placeId)?'APPROVED':'NOT_SELECTED',note:selection.has(p.id+'|'+p.placeId)?approved.find(x=>x.id===p.id&&x.placeId===p.placeId).reviewNote:'Đã xem; không chọn vì chưa chứng minh đúng chi nhánh, ảnh không phù hợp hoặc trùng góc đã chọn. Không đồng nghĩa nguồn không có giấy phép.'})));
fs.mkdirSync(dir+'/apply-payload',{recursive:true});
for(const {file,data}of catalogs){for(const p of data.places)for(const photo of p.photos){if(photo.file)assert(fs.statSync('backend/src/main/resources/catalog/photos/'+photo.file).size>0);if(photo.caption)assert(photo.caption.length<=240);}
 save(dir+'/apply-payload/'+file,data);
}
for(const p of approved)assert(proof[p.sourceUrl],p.sourceUrl);
const venues=catalogs.flatMap(d=>d.data.places.filter(p=>p.venue).map(p=>({...p,destinationId:d.data.id}))),direct=p=>p.photos.some(ph=>!ph.caption?.startsWith('Ảnh khách sạn'));
const summary={checkedAt:new Date().toISOString(),destinations:catalogs.length,catalogPlaces:catalogs.reduce((n,d)=>n+d.data.places.length,0),venues:venues.length,withPhotos:venues.filter(p=>p.photos.length).length,withDirectVenuePhotos:venues.filter(direct).length,withHotelContextOnly:venues.filter(p=>p.photos.length&&!direct(p)).length,withoutPhotos:venues.filter(p=>!p.photos.length).length,addedImages:approved.length,uniqueAddedImages:new Set(approved.map(p=>p.id)).size,approvedPrimaryLicenseSources:new Set(approved.map(p=>p.sourceUrl)).size,visuallyReviewedAssignments:reviewed.length,byDestination:catalogs.map(d=>{const vs=d.data.places.filter(p=>p.venue);return {id:d.data.id,name:d.data.name,venues:vs.length,withPhotos:vs.filter(p=>p.photos.length).length,missing:vs.filter(p=>!p.photos.length).length};})};
summary.unsplashPhotos=fs.existsSync('docs/research/photo-multisource-20261107/unsplash-approved.json')?read('docs/research/photo-multisource-20261107/unsplash-approved.json').length:0;
save(dir+'/coverage.json',summary);save(dir+'/missing-photo-queue.json',venues.filter(p=>!p.photos.length).map(p=>({id:p.id,name:p.name,destinationId:p.destinationId,kind:p.venue.kind,address:p.venue.address,website:p.venue.website,sourceUrl:p.venue.sourceUrl,requirement:'Ảnh đúng cơ sở/chi nhánh; đủ tác giả, giấy phép, nguồn; xem ảnh trước khi apply.'})));
const csvCell=s=>'"'+String(s??'').replaceAll('"','""')+'"';
fs.writeFileSync(dir+'/photo-coverage.csv','\uFEFF'+[['destination','placeId','name','kind','photos','role','sourceUrl'],...venues.map(p=>[p.destinationId,p.id,p.name,p.venue.kind,p.photos.length,p.photos.length?(direct(p)?'VENUE':'HOTEL_CONTEXT'):'MISSING',p.venue.sourceUrl])].map(r=>r.map(csvCell).join(',')).join('\n')+'\n');
const base=read(dir+'/baseline.json').flatMap(d=>d.places).filter(p=>p.venue),before=base.filter(p=>p.photos.length).length;
fs.writeFileSync(dir+'/README.md',`# Bổ sung ảnh cơ sở — 07/11/2026\n\nĐây là kết quả bổ sung ảnh sau đợt research 500 hồ sơ. Catalog vẫn có ${summary.catalogPlaces} địa điểm tại ${summary.destinations} điểm đến. Chỉ ảnh và chú thích ảnh được cập nhật; tên, vị trí, nội dung, giá và giờ phục vụ được giữ nguyên.\n\n- Trước đợt này: **${before}/${summary.venues} cơ sở có ảnh**.\n- Hiện tại: **${summary.withPhotos}/${summary.venues} cơ sở có ảnh**, gồm ${summary.withDirectVenuePhotos} cơ sở có ảnh đúng nơi và ${summary.withHotelContextOnly} quán có ảnh khách sạn chứa quán, ghi rõ “Ảnh khách sạn”.\n- Bổ sung ${summary.addedImages} ảnh đã xem và đối chiếu giấy phép trên trang nguồn chính. Không dùng ảnh món chung thay ảnh chụp tại quán.\n- **${summary.withoutPhotos} cơ sở còn thiếu ảnh**; chưa thể gọi là hoàn thiện hình ảnh. Xem [hàng chờ](missing-photo-queue.json) và [CSV theo cơ sở](photo-coverage.csv).\n\n## Dữ liệu để áp dụng\n\n[20 tệp catalog hiện tại](apply-payload/) chứa đủ thông tin đang dùng trong app. Ảnh cục bộ ở backend/src/main/resources/catalog/photos/ với tên venue-fill-*.jpg; phải đi kèm khi đóng gói. [coverage.json](coverage.json) thống kê theo địa phương; [apply-audit.json](apply-audit.json) kiểm tra bảo toàn trường dữ liệu; [approved.json](approved.json) giữ tác giả, giấy phép, đường dẫn nguồn và quyết định duyệt; [primary-license-proof.json](primary-license-proof.json) giữ bằng chứng giấy phép.\n\n## Quy tắc và giới hạn\n\nẢnh Commons/Flickr chỉ dùng khi giấy phép phù hợp và đã xem đúng chủ thể. Kết quả trùng tên ở nước ngoài, ảnh cũ của chi nhánh đã chuyển, quảng cáo đăng lại và ảnh món không xác định quán được giữ ngoài catalog. Ảnh lịch sử/nhìn từ khách sạn có chú thích; không dùng để khẳng định diện mạo hiện tại. Nhà hàng dùng ảnh khách sạn phải được operator xác nhận trong cùng khách sạn, có bằng chứng ở [property-context-photos.json](property-context-photos.json). Khi có ảnh riêng của outlet, ảnh khách sạn bổ sung trong đợt này được thay bằng ảnh outlet.\n\nMột số nguồn giới hạn tốc độ; các lần tải bị giới hạn được lưu và dừng theo Retry-After. Có thêm ảnh Unsplash đã xác minh, hotlink và ghi công tác giả; bằng chứng ở ../photo-multisource-20261107/unsplash-approved.json. Không phát sinh dịch vụ ảnh trả phí.\n\n## Kiểm tra\n\nBackend: 31 kiểm tra catalog/domain/API và checkstyle đã qua. Frontend: 436 kiểm tra, typecheck, lint và build đã qua. Kiểm tra live mobile 390px và desktop 1440px xác nhận ảnh tải được, chú thích hiển thị, chọn cơ sở và lưu/tải lại chuyến đi hoạt động. Bằng chứng live được lưu trong .logs/photo-fill-20261107/.\n`);
console.log(JSON.stringify({...summary,byDestination:undefined}));
